/**
 * POST /api/portraits/generate
 *
 * DUAL-FLOW: Works for both guests and authenticated subscribers.
 *
 * Runs the full portrait generation pipeline:
 *   analyze → build prompt → generate → watermark → store
 *
 * The portraitId must have been created via /api/portraits/upload-complete first.
 * The caller identifies themselves via sessionId (cookie) or Clerk auth.
 *
 * Authorization: a portrait can only be generated by its owner
 *   - Guest:      sessionId must match portrait.sessionId
 *   - Subscriber: userId must match portrait.userId (or portrait.userId is null and sessionId matches)
 */

import { after, NextRequest, NextResponse } from "next/server";
import { auth } from "@clerk/nextjs/server";
import { prisma } from "@/lib/prisma";
import { generatePortrait } from "@/lib/services/portrait-generation";
import { checkPreviewGate, clientIp, isNewPreviewer } from "@/lib/services/preview-gate";
import { capturePreviewer } from "@/lib/services/mautic";
import { trackMetaEvent, fbcFromFbclid } from "@/lib/services/meta-events";
import { publishProgress } from "@/lib/services/portrait-progress";
import { issuePortraitReturn } from "@/lib/services/portrait-return";
import { trackTikTokEvent } from "@/lib/services/tiktok-events";
import { attributionFromRequest, clientIp as analyticsClientIp, logAnalyticsEvent } from "@/lib/services/analytics";

// The synchronous pipeline (analysis → stand-in + fidelity gate → swap →
// acceptance gate, each leg with retries) routinely exceeds the project's
// 300s default — a live run died at FUNCTION_INVOCATION_TIMEOUT mid-stand-in
// (2026-07-12). 800s is the Fluid compute maximum on this plan.
export const maxDuration = 800;

export async function POST(request: NextRequest) {
  try {
    // --- Auth: optional ---
    let userId: string | null = null;
    try {
      const { userId: clerkUserId } = await auth();
      userId = clerkUserId;
    } catch {
      // Guest flow
    }

    // --- Parse request body ---
    let body: {
      portraitId?: string;
      stylePackSlug?: string;
      styleVariantSlug?: string;
      sessionId?: string;
      userScene?: string;
      email?: string;
      captchaToken?: string;
      marketingConsent?: boolean;
    };

    try {
      body = await request.json();
    } catch {
      return NextResponse.json(
        { success: false, error: "Invalid JSON body" },
        { status: 400 }
      );
    }

    const { portraitId, stylePackSlug, styleVariantSlug, userScene } = body;
    const sessionId =
      request.cookies.get("portrait_session_id")?.value || body.sessionId;
    const captchaToken = body.captchaToken;

    if (!portraitId || !stylePackSlug || !styleVariantSlug) {
      return NextResponse.json(
        {
          success: false,
          error: "Required fields: portraitId, stylePackSlug, styleVariantSlug",
        },
        { status: 400 }
      );
    }

    // Custom scene requires userScene
    if (stylePackSlug === "custom-scene" && !userScene) {
      return NextResponse.json(
        { success: false, error: "Custom scene requires a userScene description" },
        { status: 400 }
      );
    }

    // --- Load portrait and verify ownership ---
    const portrait = await prisma.portrait.findUnique({
      where: { id: portraitId },
    });

    if (!portrait) {
      return NextResponse.json(
        { success: false, error: "Portrait not found" },
        { status: 404 }
      );
    }

    // Authorization check:
    // - Subscriber: must match userId
    // - Guest: must match sessionId
    const isOwner =
      (userId && portrait.userId === userId) ||
      (!userId && sessionId && portrait.sessionId === sessionId) ||
      (userId && !portrait.userId && sessionId && portrait.sessionId === sessionId);

    if (!isOwner) {
      return NextResponse.json(
        { success: false, error: "Not authorized to generate this portrait" },
        { status: 403 }
      );
    }

    // --- Check portrait is in a generatable state ---
    const processing = ["queued", "analyzing", "generating"].includes(portrait.status);
    const processingIsFresh =
      processing && Date.now() - portrait.updatedAt.getTime() < 15 * 60_000;
    if (processingIsFresh) {
      return NextResponse.json(
        {
          success: false,
          error: "Portrait is already being processed",
          code: "already_processing",
          portraitId,
        },
        { status: 409 }
      );
    }

    if (portrait.status === "purchased") {
      return NextResponse.json(
        { success: false, error: "This portrait has already been purchased" },
        { status: 409 }
      );
    }

    // --- Preview gate ---
    //
    // Everything past this point costs money (Claude Vision, the stand-in
    // provider, the swap, the upscale), so the gate sits HERE rather than
    // between generation and viewing. A refusal below has spent nothing.
    //
    // It runs after the 403/409 checks so a request that was never going to
    // generate anything does not consume the caller's quota.
    const accountEmail = userId
      ? (
          await prisma.user.findUnique({
            where: { id: userId },
            select: { email: true },
          })
        )?.email
      : null;

    const gate = await checkPreviewGate({
      sessionId: portrait.sessionId,
      ip: clientIp(request.headers),
      portraitId,
      accountEmail,
      captchaToken,
    });

    if (!gate.allowed) {
      const attribution = attributionFromRequest(request);
      await logAnalyticsEvent({
        eventName: "generation_blocked",
        sessionId: portrait.sessionId,
        userId,
        portraitId,
        ...attribution,
        metadata: {
          code: gate.code,
          previewsUsed: gate.previewsUsed,
          stylePackSlug,
          styleVariantSlug,
        },
        ip: analyticsClientIp(request.headers),
        userAgent: request.headers.get("user-agent"),
      });
      return NextResponse.json(
        {
          success: false,
          error: gate.error,
          code: gate.code,
          previewsUsed: gate.previewsUsed,
        },
        {
          status:
            gate.code === "rate_limited" || gate.code === "daily_limit" ? 429 : 403,
        }
      );
    }

    // Capture the verified account address before generating. The
    // post-generation push below enriches the same row with the preview URL.
    if (gate.email && (await isNewPreviewer(gate.email))) {
      await capturePreviewer({
        email: gate.email,
        subjectType: portrait.subjectType,
        style: portrait.stylePackSlug,
      });
    }

    // Snapshot request-scoped values before the response closes. The generation
    // itself runs in Next's after() lifecycle, so a sleeping phone or closed tab
    // cannot cancel the server-owned job.
    const visitorIp =
      request.headers.get("x-forwarded-for")?.split(",")[0]?.trim() || null;
    const visitorUa = request.headers.get("user-agent");
    const url = new URL(request.url);
    const ttclid =
      url.searchParams.get("ttclid") || request.cookies.get("ttclid")?.value || null;
    const ttp = request.cookies.get("_ttp")?.value || null;
    const fbclid = url.searchParams.get("fbclid");
    const fbc =
      request.cookies.get("_fbc")?.value || (fbclid ? fbcFromFbclid(fbclid) : null);
    const fbp = request.cookies.get("_fbp")?.value || null;
    const eventEmail = gate.email || accountEmail || null;
    const contentName = `${stylePackSlug} ${styleVariantSlug}`.trim();
    const attribution = attributionFromRequest(request);
    const analyticsIp = analyticsClientIp(request.headers);

    await prisma.portrait.update({
      where: { id: portraitId },
      data: {
        status: "queued",
        stylePackSlug,
        styleVariantSlug,
        errorMessage: null,
        updatedAt: new Date(),
      },
    });

    after(async () => {
      try {
        const result = await generatePortrait({
          portraitId,
          stylePackSlug,
          styleVariantSlug,
          userId,
          userScene,
        });

        if (!result.success) {
          await logAnalyticsEvent({
            eventName: "generation_failed",
            sessionId: portrait.sessionId,
            userId,
            portraitId,
            ...attribution,
            metadata: {
              error: result.error,
              errorType: result.errorType,
              stylePackSlug,
              styleVariantSlug,
            },
            ip: analyticsIp,
            userAgent: visitorUa,
          });
          await publishProgress(portraitId, {
            stage: "failed",
            label: result.error ?? "Generation failed.",
          });
          return;
        }

        if (gate.email) {
          let returnUrl: string | null = null;
          try {
            returnUrl = await issuePortraitReturn(
              portraitId,
              gate.email,
              body.marketingConsent === true
            );
          } catch (error) {
            console.error("[Generate] Preview ready but return email failed", error);
          }
          await capturePreviewer({
            email: gate.email,
            subjectType: result.subjectType ?? portrait.subjectType,
            style: stylePackSlug,
            previewUrl: result.previewImageUrl,
            returnUrl,
          });
        }

        const previewPageUrl =
          `${process.env.NEXT_PUBLIC_APP_URL || "https://imagecrafter.app"}/portraits/${portraitId}/preview`;
        await trackTikTokEvent({
          event: "CustomizeProduct",
          eventId: `image_created_${portraitId}`,
          url: previewPageUrl,
          email: eventEmail,
          externalId: userId,
          ip: visitorIp,
          userAgent: visitorUa,
          ttclid,
          ttp,
          contentId: portraitId,
          contentName,
        });
        await trackMetaEvent({
          event: "CustomizeProduct",
          eventId: `image_created_${portraitId}`,
          url: previewPageUrl,
          email: eventEmail,
          externalId: userId,
          ip: visitorIp,
          userAgent: visitorUa,
          fbc,
          fbp,
          contentId: portraitId,
          contentName,
        });
        await logAnalyticsEvent({
          eventName: "preview_created",
          sessionId: portrait.sessionId,
          userId,
          portraitId,
          ...attribution,
          metadata: {
            stylePackSlug,
            styleVariantSlug,
            subjectType: result.subjectType ?? portrait.subjectType,
            previewImageUrl: result.previewImageUrl,
          },
          ip: analyticsIp,
          userAgent: visitorUa,
        });
      } catch (error) {
        console.error("[Generate] Background generation failed:", error);
        await prisma.portrait.update({
          where: { id: portraitId },
          data: {
            status: portrait.previewImageUrl ? "preview" : "failed",
            errorMessage: portrait.previewImageUrl
              ? null
              : "Generation stopped unexpectedly. Please try again.",
          },
        });
        await publishProgress(portraitId, {
          stage: "failed",
          label: "Generation stopped unexpectedly.",
        });
      }
    });

    return NextResponse.json({
      success: true,
      accepted: true,
      portraitId,
      status: "queued",
    }, { status: 202 });
  } catch (error) {
    console.error("[Generate] Unexpected error:", error);
    return NextResponse.json(
      { success: false, error: "Generation failed. Please try again." },
      { status: 500 }
    );
  }
}
